def compute(vars):
    value = vars["v1"] + vars["v2"]
    return {
        "value": value,
        "trace": {
            "severance_and_related_charges": vars["v1"],
            "lease_termination_costs": vars["v2"],
            "total_balance": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
